using EjemploABM.Controladores; using EjemploABM.Servicios; using System; using System.Drawing; using System.Linq; using System.Windows.Forms;
namespace EjemploABM.ControlesDeUsuario { public class EnviosMailForm:Form { DataGridView grilla=new DataGridView(); Button reintentar=new Button(); public EnviosMailForm(){Text="Historial de envíos de mail";StartPosition=FormStartPosition.CenterParent;Size=new Size(1050,560);grilla.Dock=DockStyle.Fill;grilla.ReadOnly=true;grilla.AutoGenerateColumns=true;grilla.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;reintentar.Text="Reintentar seleccionado";reintentar.Dock=DockStyle.Bottom;reintentar.Height=38;reintentar.Click+=(s,e)=>Reintentar();Controls.Add(grilla);Controls.Add(reintentar);Cargar();}void Cargar(){try{grilla.DataSource=EmailEnvio_Controller.ObtenerTodos();}catch(Exception ex){MessageBox.Show(ex.Message,"Envíos",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}void Reintentar(){if(grilla.CurrentRow==null)return;var id=Convert.ToInt32(grilla.CurrentRow.Cells["Id"].Value);try{EmailService.Reintentar(id);MessageBox.Show("El envío fue realizado.","Envíos",MessageBoxButtons.OK,MessageBoxIcon.Information);Cargar();}catch(Exception ex){MessageBox.Show("No se pudo reenviar: "+ex.Message,"Envíos",MessageBoxButtons.OK,MessageBoxIcon.Warning);Cargar();}} } }
